sys_script_include.script:
var ResumeGeminiParser = Class.create();
ResumeGeminiParser.prototype = {
    initialize: function () {},

    parseProfile: function (profileSysId) {
        var profile = new GlideRecord("x_2311790_skills_0_student_profile");

        if (!profile.get(profileSysId)) {
            throw new Error("Student Profile record not found");
        }

        var attachment = new GlideRecord("sys_attachment");
        attachment.addQuery("table_name", "x_2311790_skills_0_student_profile");
        attachment.addQuery("table_sys_id", profileSysId);
        attachment.addQuery("content_type", "application/pdf");
        attachment.orderByDesc("sys_created_on");
        attachment.setLimit(1);
        attachment.query();

        if (!attachment.next()) {
            throw new Error("No PDF attachment found");
        }

        var gsa = new GlideSysAttachment();
        var pdfBase64 = gsa.getContentBase64(attachment);

        if (!pdfBase64) {
            throw new Error("Could not read PDF attachment");
        }

        // Configure this REST Message method to POST the Gemini request.
        var requestBody = {
            contents: [{
                parts: [
                    {
                        text: "Read this resume. Return JSON with string keys headline and parsed_resume. Keep both factual; do not invent details."
                    },
                    {
                        inline_data: {
                            mime_type: "application/pdf",
                            data: String(pdfBase64)
                        }
                    }
                ]
            }],
            generationConfig: {
                responseMimeType: "application/json"
            }
        };

        var request = new sn_ws.RESTMessageV2(
            "YOUR_REST_MESSAGE_NAME",
            "YOUR_METHOD_NAME"
        );
        request.setRequestBody(JSON.stringify(requestBody));

        var response = request.execute();
        var status = response.getStatusCode();

        if (status < 200 || status >= 300) {
            throw new Error("Gemini request failed; HTTP " + status);
        }

        var result = JSON.parse(response.getBody());
        var generatedText = result.candidates[0].content.parts[0].text;
        var parsed = JSON.parse(generatedText);

        if (!parsed.headline || !parsed.parsed_resume) {
            throw new Error("Gemini response did not contain both required fields");
        }

        // TODO: Call the embedding REST Message here, then save its vector.
        profile.setValue("u_headline", String(parsed.headline));
        profile.setValue("u_parsed_resume", String(parsed.parsed_resume));
        profile.update();
    },

    type: "ResumeGeminiParser"
};
